/* VARIANT H · STORYBOOK */
[class*="section-"] {
  --sb-ground: #FAF4EA;
  --sb-blush: #F3D6D2;
  --sb-mint: #DCE9DC;
  --sb-butter: #F3E5B8;
  --sb-wine: #571726;
  --sb-display: "Bodoni Moda", Didot, "Times New Roman", serif;
  --sb-sans: "Jost", "Helvetica Neue", Arial, sans-serif;
  --sb-mono: "IBM Plex Mono", monospace;
  background: var(--sb-ground);
  color: var(--sb-wine);
  box-sizing: border-box;
}
[class*="section-"] *, [class*="section-"] *::before, [class*="section-"] *::after { box-sizing: border-box; }
[class*="section-"] :is(p,a,button,input,textarea,label,span) { font-family: var(--sb-sans) !important; }
[class*="section-"] :is(h1,h2,h3,h4,.text-h2,.title) { font-family: var(--sb-display) !important; font-weight: 400 !important; color: var(--sb-wine) !important; }
[class*="section-"] :is(.q-btn,.q-card,.q-field__control) { border-radius: 2px !important; box-shadow: none !important; }

/* HERO · framed plate */
[class*="section-hero-h---framed-plate-"] { padding: 64px 24px 72px !important; background: var(--sb-blush) !important; text-align: center; }
[class*="section-hero-h---framed-plate-"] :is(.q-card,.q-card__section,[data-test-id="generic-carousel"]) { max-width: 820px !important; margin: 0 auto !important; padding: 0 !important; background: transparent !important; }
[class*="section-hero-h---framed-plate-"] :is(.swiper,.swiper-wrapper,.swiper-slide,[class*="carousel-item-"]) { height: auto !important; min-height: 0 !important; }
[class*="section-hero-h---framed-plate-"] .row.justify-center.position-relative { display: flex !important; flex-direction: column !important; align-items: center !important; height: auto !important; min-height: 0 !important; overflow: visible !important; }
[class*="section-hero-h---framed-plate-"] img.full-width,
[class*="section-hero-h---framed-plate-"] [class*="carousel-item-"] img { position: static !important; width: min(100%,720px) !important; height: auto !important; aspect-ratio: 4/3; object-fit: cover !important; object-position: center !important; margin: 5px auto 36px !important; border: 1px solid var(--sb-wine) !important; outline: 1px solid var(--sb-wine) !important; outline-offset: 4px; }
[class*="section-hero-h---framed-plate-"] .flex.absolute-bottom { position: static !important; inset: auto !important; width: 100% !important; padding: 0 24px !important; background: transparent !important; color: var(--sb-wine) !important; }
[class*="section-hero-h---framed-plate-"] .flex.absolute-bottom .container { width: 100% !important; max-width: 720px !important; padding: 0 !important; }
[class*="section-hero-h---framed-plate-"] .col.message { width: 100% !important; max-width: 720px !important; margin: 0 auto !important; padding: 0 !important; text-align: center !important; }
[class*="section-hero-h---framed-plate-"] .col.message::before { content: "Now showing"; display: block; margin: 0 0 10px; font-family: var(--sb-sans); font-size: 14px; letter-spacing: .2em; font-variant-caps: all-small-caps; color: var(--sb-wine); }
[class*="section-hero-h---framed-plate-"] .title { margin: 0 0 12px !important; font-size: clamp(38px,5vw,52px) !important; line-height: 1.05 !important; letter-spacing: -.02em !important; color: var(--sb-wine) !important; text-shadow: none !important; }
[class*="section-hero-h---framed-plate-"] .subtitle { margin: 0 0 24px !important; font-size: 14px !important; line-height: 1.6 !important; letter-spacing: .18em !important; font-variant-caps: all-small-caps; color: var(--sb-wine) !important; text-shadow: none !important; }
[class*="section-hero-h---framed-plate-"] .q-btn { min-height: 46px !important; padding: 0 28px !important; background: transparent !important; color: var(--sb-wine) !important; border: 1px solid var(--sb-wine) !important; }
[class*="section-hero-h---framed-plate-"] .q-btn :is(.q-btn__content,span) { color: var(--sb-wine) !important; font-size: 14px !important; letter-spacing: .18em !important; font-variant-caps: all-small-caps; }
[class*="section-hero-h---framed-plate-"] :is(.swiper-button-prev,.swiper-button-next) { color: var(--sb-wine) !important; }
[class*="section-hero-h---framed-plate-"] .swiper-pagination { position: static !important; margin-top: 20px; }
[class*="section-hero-h---framed-plate-"] .swiper-pagination-bullet { width: 6px !important; height: 6px !important; margin: 0 8px !important; border-radius: 0 !important; background: var(--sb-wine) !important; }

/* EVENTS · invitations */
[class*="section-events-h---invitations-"] { padding: 72px 24px 80px !important; background: var(--sb-ground) !important; }
[class*="section-events-h---invitations-"] > * { max-width: 1080px !important; margin: 0 auto !important; padding: 0 !important; }
[class*="section-events-h---invitations-"] .sb-events { color: var(--sb-wine); text-align: center; }
[class*="section-events-h---invitations-"] .sb-events__kicker { margin: 0 0 10px; font-size: 14px; letter-spacing: .2em; font-variant-caps: all-small-caps; }
[class*="section-events-h---invitations-"] .sb-events__title { margin: 0 0 42px !important; font-size: clamp(38px,5vw,48px) !important; line-height: 1.1 !important; }
[class*="section-events-h---invitations-"] .sb-events__grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 24px; }
[class*="section-events-h---invitations-"] .sb-invite { position: relative; min-height: 330px; padding: 44px 28px; border: 1px solid var(--sb-wine); outline: 1px solid var(--sb-wine); outline-offset: -6px; display: flex; flex-direction: column; align-items: center; justify-content: center; }
[class*="section-events-h---invitations-"] .sb-invite:nth-child(1) { background: var(--sb-blush); }
[class*="section-events-h---invitations-"] .sb-invite:nth-child(2) { background: var(--sb-mint); }
[class*="section-events-h---invitations-"] .sb-invite:nth-child(3) { background: var(--sb-butter); }
[class*="section-events-h---invitations-"] .sb-invite__kicker { margin: 0 0 12px; font-size: 13px; letter-spacing: .2em; font-variant-caps: all-small-caps; }
[class*="section-events-h---invitations-"] .sb-invite h3 { margin: 0 !important; font-size: 29px !important; line-height: 1.15 !important; }
[class*="section-events-h---invitations-"] .sb-invite__rule { width: 42px; height: 1px; margin: 22px 0; background: var(--sb-wine); position: relative; }
[class*="section-events-h---invitations-"] .sb-invite__rule::after { content: ""; position: absolute; width: 6px; height: 6px; left: 18px; top: -2px; background: var(--sb-wine); }
[class*="section-events-h---invitations-"] .sb-invite p { max-width: 30ch; margin: 0 0 22px !important; font-size: 15px !important; line-height: 1.7 !important; color: var(--sb-wine) !important; }
[class*="section-events-h---invitations-"] .sb-invite a { display: inline-block; padding: 10px 18px; border: 1px solid var(--sb-wine); color: var(--sb-wine) !important; font-size: 13px !important; letter-spacing: .18em; font-variant-caps: all-small-caps; text-decoration: none !important; }

/* FOOD · framed bill of fare */
[class*="section-food-h---framed-bill-of-fare-"] { padding: 72px 24px 84px !important; background: var(--sb-butter) !important; text-align: center; }
[class*="section-food-h---framed-bill-of-fare-"] .container { max-width: 620px !important; margin: 0 auto !important; padding: 0 !important; }
[class*="section-food-h---framed-bill-of-fare-"] .container > .row:first-child { justify-content: center !important; padding: 0 0 34px !important; }
[class*="section-food-h---framed-bill-of-fare-"] h2 { margin: 0 !important; font-size: clamp(38px,5vw,48px) !important; line-height: 1.1 !important; text-align: center !important; }
[class*="section-food-h---framed-bill-of-fare-"] h2::before { content: "Bill of fare"; display: block; margin-bottom: 8px; font-family: var(--sb-sans); font-size: 14px; letter-spacing: .2em; font-variant-caps: all-small-caps; }
[class*="section-food-h---framed-bill-of-fare-"] .full-width.q-py-md.row { display: block !important; padding: 5px !important; border: 1px solid var(--sb-wine); outline: 1px solid var(--sb-wine); outline-offset: -5px; }
[class*="section-food-h---framed-bill-of-fare-"] :is(.col-2,.col-md-2) { display: none !important; }
[class*="section-food-h---framed-bill-of-fare-"] :is(.col-12.col-md-10,.col-md-10) { width: 100% !important; max-width: 100% !important; padding: 28px 42px !important; }
[class*="section-food-h---framed-bill-of-fare-"] .concessions-menu-category-sections-root .text-bold > p { margin: 28px 0 18px !important; font-family: var(--sb-display) !important; font-size: 32px !important; font-weight: 400 !important; color: var(--sb-wine) !important; text-align: center !important; }
[class*="section-food-h---framed-bill-of-fare-"] .row.justify-start.items-stretch { display: block !important; margin: 0 !important; }
[class*="section-food-h---framed-bill-of-fare-"] .row.justify-start.items-stretch > .q-card.q-card--bordered { width: 100% !important; max-width: none !important; min-height: 0 !important; margin: 0 !important; padding: 20px 8px 28px !important; background: transparent !important; border: 0 !important; border-bottom: 1px solid rgba(87,23,38,.28) !important; color: var(--sb-wine) !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-img.q-img--menu { display: none !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card__section { padding: 0 !important; text-align: center !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card :is(.text-subtitle2,.text-weight-bold) { font-family: var(--sb-display) !important; font-size: 24px !important; font-weight: 400 !important; line-height: 1.2 !important; color: var(--sb-wine) !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card .opacity-80 { max-width: 40ch; margin: 8px auto 0; font-size: 15px !important; line-height: 1.6 !important; color: var(--sb-wine) !important; opacity: .78 !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card .row.items-center.justify-between { display: flex !important; flex-direction: column !important; justify-content: center !important; gap: 12px; margin-top: 12px !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card .col.text-weight-regular,
[class*="section-food-h---framed-bill-of-fare-"] .q-card .col.text-weight-regular span { font-family: var(--sb-mono) !important; font-size: 14px !important; color: var(--sb-wine) !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card .q-btn { min-height: 0 !important; padding: 0 !important; background: transparent !important; color: var(--sb-wine) !important; }
[class*="section-food-h---framed-bill-of-fare-"] .q-card .q-btn :is(span,.q-btn__content) { color: var(--sb-wine) !important; font-size: 13px !important; letter-spacing: .18em; font-variant-caps: all-small-caps; }

/* CONTACT · the letter */
[class*="section-contact-h---the-letter-"] { padding: 80px 24px 88px !important; background: var(--sb-mint) !important; }
[class*="section-contact-h---the-letter-"] .q-card { max-width: 560px !important; margin: 5px auto !important; padding: 50px 48px !important; background: transparent !important; border: 1px solid var(--sb-wine) !important; outline: 1px solid var(--sb-wine) !important; outline-offset: 4px; color: var(--sb-wine) !important; }
[class*="section-contact-h---the-letter-"] .q-card__section { padding: 0 !important; }
[class*="section-contact-h---the-letter-"] .q-card__section:first-child { margin-bottom: 28px !important; text-align: center !important; }
[class*="section-contact-h---the-letter-"] .text-h2 { margin: 0 !important; font-size: clamp(38px,5vw,48px) !important; line-height: 1.1 !important; color: var(--sb-wine) !important; }
[class*="section-contact-h---the-letter-"] .text-h2::after { content: ""; display: block; width: 6px; height: 6px; margin: 20px auto 0; background: var(--sb-wine); }
[class*="section-contact-h---the-letter-"] .q-card__section.row.q-col-gutter-md { display: block !important; }
[class*="section-contact-h---the-letter-"] .q-card__section.row.q-col-gutter-md > :is(.col-6,.col-12) { width: 100% !important; max-width: 100% !important; padding: 0 !important; }
[class*="section-contact-h---the-letter-"] .q-field { margin: 0 0 18px !important; }
[class*="section-contact-h---the-letter-"] .q-field__control,
[class*="section-contact-h---the-letter-"] .q-field__control.bg-white { min-height: 54px !important; background: transparent !important; border: 1px solid var(--sb-wine) !important; }
[class*="section-contact-h---the-letter-"] .q-field__control::before,
[class*="section-contact-h---the-letter-"] .q-field__control::after { display: none !important; }
[class*="section-contact-h---the-letter-"] .q-field__label { width: 100%; text-align: center; color: var(--sb-wine) !important; font-size: 13px !important; letter-spacing: .16em; font-variant-caps: all-small-caps; }
[class*="section-contact-h---the-letter-"] :is(.q-field__native,input,textarea) { text-align: center !important; color: var(--sb-wine) !important; font-size: 15px !important; }
[class*="section-contact-h---the-letter-"] textarea.q-field__native { min-height: 110px !important; }
[class*="section-contact-h---the-letter-"] .q-card__section.row.items-center.justify-center { padding-top: 6px !important; }
[class*="section-contact-h---the-letter-"] .q-card__section.row.items-center.justify-center .q-btn { min-height: 46px !important; padding: 0 28px !important; background: transparent !important; color: var(--sb-wine) !important; border: 1px solid var(--sb-wine) !important; }
[class*="section-contact-h---the-letter-"] .q-card__section.row.items-center.justify-center :is(.q-btn__content,span) { color: var(--sb-wine) !important; font-size: 13px !important; letter-spacing: .18em; font-variant-caps: all-small-caps; }

@media (max-width: 899px) {
  [class*="section-hero-h---framed-plate-"] { padding: 28px 12px 44px !important; }
  [class*="section-hero-h---framed-plate-"] img.full-width,
  [class*="section-hero-h---framed-plate-"] [class*="carousel-item-"] img { width: calc(100% - 10px) !important; margin-bottom: 30px !important; }
  [class*="section-hero-h---framed-plate-"] .title { font-size: 32px !important; }
  [class*="section-events-h---invitations-"] { padding: 52px 12px 60px !important; }
  [class*="section-events-h---invitations-"] .sb-events__grid { grid-template-columns: 1fr; gap: 18px; }
  [class*="section-events-h---invitations-"] .sb-invite { min-height: 290px; }
  [class*="section-food-h---framed-bill-of-fare-"] { padding: 52px 16px 60px !important; }
  [class*="section-food-h---framed-bill-of-fare-"] :is(.col-12.col-md-10,.col-md-10) { padding: 18px 16px !important; }
  [class*="section-contact-h---the-letter-"] { padding: 54px 12px 62px !important; }
  [class*="section-contact-h---the-letter-"] .q-card { width: calc(100% - 10px) !important; padding: 38px 22px !important; }
}

/* QA repair · image-free hero and INDY mobile preview */
[class*="section-hero-h---framed-plate-"] .row.justify-center.position-relative {
  width: min(100%,720px) !important;
  min-height: 360px !important;
  margin: 5px auto 36px !important;
  padding: 0 !important;
  background: var(--sb-ground) !important;
  border: 1px solid var(--sb-wine) !important;
  outline: 1px solid var(--sb-wine) !important;
  outline-offset: 4px;
}
[class*="section-hero-h---framed-plate-"] .flex.absolute-center {
  position: static !important;
  inset: auto !important;
  transform: none !important;
  width: 100% !important;
  min-height: 360px !important;
  padding: 54px 32px !important;
  background: transparent !important;
  color: var(--sb-wine) !important;
}
[class*="section-hero-h---framed-plate-"] .flex.absolute-center .container {
  width: 100% !important;
  max-width: 620px !important;
  margin: auto !important;
  padding: 0 !important;
}
.media_container.mobile [class*="section-hero-h---framed-plate-"] { padding: 28px 12px 44px !important; }
.media_container.mobile [class*="section-hero-h---framed-plate-"] .row.justify-center.position-relative {
  width: calc(100% - 10px) !important;
  min-height: 300px !important;
  margin: 5px auto 30px !important;
}
.media_container.mobile [class*="section-hero-h---framed-plate-"] .flex.absolute-center {
  min-height: 300px !important;
  padding: 38px 20px !important;
}
.media_container.mobile [class*="section-hero-h---framed-plate-"] .title { font-size: 32px !important; }
.media_container.mobile [class*="section-events-h---invitations-"] { padding: 52px 12px 60px !important; }
.media_container.mobile [class*="section-events-h---invitations-"] .sb-events__grid { grid-template-columns: 1fr !important; gap: 18px !important; }
.media_container.mobile [class*="section-events-h---invitations-"] .sb-invite { min-height: 290px !important; }
.media_container.mobile [class*="section-food-h---framed-bill-of-fare-"] { padding: 52px 16px 60px !important; }
.media_container.mobile [class*="section-food-h---framed-bill-of-fare-"] :is(.col-12.col-md-10,.col-md-10) { padding: 18px 16px !important; }
.media_container.mobile [class*="section-contact-h---the-letter-"] { padding: 54px 12px 62px !important; }
.media_container.mobile [class*="section-contact-h---the-letter-"] .q-card { width: calc(100% - 10px) !important; padding: 38px 22px !important; }
